inputs = ['ejxh', 'zdgd', 'jfdh', 'egx', 'czub']
outputs = ['ejxkg', 'zdgd', 'jxzkgdkg', 'egx', 'czuw']

print("Detailed character-by-character analysis:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"\n{i}: '{inp}' -> '{outp}'")
    if inp != outp:
        # Find the minimal edit operations
        min_len = min(len(inp), len(outp))

        # Look for the first difference
        first_diff_pos = None
        for j in range(min_len):
            if inp[j] != outp[j]:
                first_diff_pos = j
                break

        if first_diff_pos is not None:
            print(f"  First difference at position {first_diff_pos}")
            print(f"  Before: '{inp[first_diff_pos:]}'")
            print(f"  After:  '{outp[first_diff_pos:]}'")

        # Check if we're adding or removing
        if len(inp) < len(outp):
            print(f"  Length increased by {len(outp) - len(inp)}")
        elif len(inp) > len(outp):
            print(f"  Length decreased by {len(inp) - len(outp)}")
        else:
            print("  Same length")
    else:
        print("  No change")

